// ==========================================
// 1. Puxa dados organizados do nó de limpeza
// ==========================================
const nomeDoNoDeLimpeza = "Code in JavaScript1";
const dadosOrganizados = $items(nomeDoNoDeLimpeza).map(i => i.json);

// ==========================================
// 2. Puxa o JSON bruto do Webhook
// ==========================================
const webhook = $('Webhook').first().json.body || $('Webhook').first().json;
const tripInfo = webhook.trip || {};

// ==========================================
// 3. Pega os resultados do OpenCage
// ==========================================
const geocodeResults = $input.all();

function extrairComponentes(item) {
    const result = item.json.results && item.json.results[0] ? item.json.results[0] : null;
    const geometry = result ? result.geometry : { lat: "", lng: "" };
    const components = result ? (result.components || {}) : {};
    return {
        lat: (geometry.lat || "").toString(),
        lng: (geometry.lng || "").toString(),
        neighborhood: components.neighbourhood || components.suburb || components.neighborhood || "",
        city: components.city || components.town || components.municipality || components.village || "",
        state: components.state_code || components.state || "",
        postal_code: components.postcode || ""
    };
}

let destInfo = { lat: "", lng: "", neighborhood: "", city: "", state: "", postal_code: "" };
const userInfo = {};

// Item 0 = Destino, resto = Passageiros
geocodeResults.forEach((item, index) => {
    const info = extrairComponentes(item);
    if (index === 0) {
        destInfo = info;
    } else {
        const passageiroId = dadosOrganizados.filter(p => p.type === "passageiro")[index - 1]?.id;
        if (passageiroId) userInfo[passageiroId] = info;
    }
});

// ==========================================
// 4. Montagem do pickup_time (prioridade: serviceTime do 1º passageiro)
// ==========================================
let pickupTimeUnix = Math.floor(Date.now() / 1000);
try {
    if (tripInfo.scheduledDate) {
        let timeString = "";
        if (tripInfo.passengers && tripInfo.passengers.length > 0) {
            timeString = tripInfo.passengers[0].serviceTime;
        }
        if (!timeString) timeString = tripInfo.departureTime || tripInfo.arrivalTime || "00:00";

        let [d, m, y] = tripInfo.scheduledDate.split('/');
        let [h, min] = timeString.split(':');
        if (!y) y = new Date().getFullYear().toString();
        else if (y.length === 2) y = "20" + y;

        const pad = (num) => String(num).padStart(2, '0');
        const dataIsoBRT = `${y}-${pad(m)}-${pad(d)}T${pad(h || 0)}:${pad(min || 0)}:00-03:00`;
        const dateObj = new Date(dataIsoBRT);
        if (!isNaN(dateObj.getTime())) pickupTimeUnix = Math.floor(dateObj.getTime() / 1000);
    }
} catch (e) { console.log("Erro na data: ", e); }

// ==========================================
// 5. Montagem dos Usuários
// ==========================================
const finalUsers = dadosOrganizados.filter(p => p.type === "passageiro").map((u, index) => {
    const info = userInfo[u.id] || { lat: "", lng: "", neighborhood: "", city: "", state: "", postal_code: "" };
    const passageiroOriginal = tripInfo.passengers?.find(p => p.name === u.name) || tripInfo.passengers?.[index] || {};
    return {
        id: u.id,
        sequence: (index * 2) + 1,
        name: u.name,
        phone: u.phone.replace(/\D/g, ""),
        passenger_re: passageiroOriginal.re || "",
        passenger_cost_center: u.costCenter,
        pickup: {
            address: u.original_address,
            neighborhood: info.neighborhood,
            city: info.city,
            state: info.state,
            postal_code: info.postal_code,
            lat: info.lat,
            lng: info.lng
        }
    };
});

// ==========================================
// 6. Montagem dos Destinos
// ==========================================
const finalDestinations = finalUsers.map((u, index) => ({
    passengerId: u.id,
    sequence: (index * 2) + 2,
    location: {
        address: tripInfo.destinations?.[0]?.location?.address || "",
        neighborhood: destInfo.neighborhood,
        city: destInfo.city,
        state: destInfo.state,
        postal_code: destInfo.postal_code,
        reference: "",
        lat: destInfo.lat,
        lng: destInfo.lng
    }
}));

// ==========================================
// 7. RETORNO FINAL
// Inclui _geocode_cache para o nó de VOLTA usar sem precisar rebuscar o HTTP Request
// ==========================================
return {
    partner: "322",
    user: tripInfo.company?.replace(/\D/g, "") || "CNPJ_VAZIO",
    password: "0104",
    request_id: `REQ-${Date.now()}`,
    pickup_time: pickupTimeUnix.toString(),
    distance: "0",
    stopped_time: "0",
    category: "taxi",
    passengers_no: finalUsers.length,
    send_sms: 1,
    suitcases_no: 0,
    requester_name: `${tripInfo.requester || ''}`,
    extra1: $('Webhook').first().json.body.trip.extra1,
    extra2: tripInfo.requester,
    payment_type: $('Webhook').first().json.body.trip.payment,
    users: finalUsers,
    destinations: finalDestinations,
    _geocode_cache: {
        destInfo: destInfo,
        userInfo: userInfo,
        dadosOrganizados: dadosOrganizados
    }
};

const payload = $input.first().json.body || $input.first().json;
const itemsToGeocode = [];

function limparEndereco(endereco) {
    if (!endereco) return "";
    let limpo = endereco;
    limpo = limpo.replace(/^\d{8}[,\s-]+/, "");
    limpo = limpo.replace(/Cidade:/gi, "");
    limpo = limpo.replace(/UF:/gi, "");
    limpo = limpo.replace(/Estado:/gi, "");
    limpo = limpo.replace(/CEP:/gi, "");
    limpo = limpo.replace(/Bairro:/gi, "");
    limpo = limpo.replace(/RUA - /gi, "");
    limpo = limpo.replace(/AVENIDA - /gi, "");
    limpo = limpo.replace(/ - Número:\s*/gi, ", ");
    limpo = limpo.replace(/ - BAIRRO /gi, ", ");
    limpo = limpo.replace(/\s+/g, " ").trim();
    if (!limpo.toLowerCase().includes("brasil")) limpo = limpo + ", Minas Gerais, Brasil";
    return limpo.trim();
}

const tripData = payload.trip || payload;

let destinoAddress = "";
if (tripData.destinations && tripData.destinations.length > 0 && tripData.destinations[0].location) {
    destinoAddress = tripData.destinations[0].location.address;
} else if (tripData.destination) {
    destinoAddress = tripData.destination;
}

if (destinoAddress) {
    itemsToGeocode.push({
        type: "destino",
        id: 0,
        address: limparEndereco(destinoAddress),
        original_address: destinoAddress
    });
}

const usersList = tripData.passengers || tripData.users || [];

if (usersList.length > 0) {
    usersList.forEach((u, index) => {
        const addressRaw = (u.pickup && u.pickup.address) ? u.pickup.address : u.address;
        itemsToGeocode.push({
            type: "passageiro",
            id: u.id || u.passengerId || String(index + 1),
            name: u.name || u.passengerName || ("Passageiro " + (index + 1)),
            phone: u.phone || u.passengerPhone || "",
            costCenter: u.costCenter || u.passenger_cost_center || u.cost_center || "",
            original_address: addressRaw,
            address: limparEndereco(addressRaw)
        });
    });
}

if (itemsToGeocode.length === 0 || (itemsToGeocode.length === 1 && itemsToGeocode[0].type === "destino")) {
    return [{ json: { erro: "Falha ao encontrar passageiros. Verifique se o JSON tem 'trip.passengers'.", payload: payload } }];
}

return itemsToGeocode.map(item => ({ json: item }));

// Puxa o JSON bruto do Webhook
const webhook = $('Webhook').first().json.body || $('Webhook').first().json;
const trip = webhook.trip || {};
const passengers = trip.passengers || [];

const dataAgendamento = trip.scheduledDate || "data informada";
let dataFormatada = dataAgendamento;
if (dataAgendamento.includes('/')) {
    const partes = dataAgendamento.split('/');
    dataFormatada = `${partes[0]}-${partes[1]}`;
}

const listaNomes = passengers.map(p => `* ${p.name}`).join('\n');
const messages = [];

passengers.forEach(p => {
    if (!p.phone) return;
    let foneString = p.phone.replace(/\D/g, "");
    if (foneString.length === 10 || foneString.length === 11) foneString = "55" + foneString;
    const horaAgendamento = p.serviceTime || trip.arrivalTime || "horário combinado";
    const nomeCompleto = p.name || "Passageiro";
    const textoMsg = `Olá ${nomeCompleto}\n\nObrigado pelo contato! Sua corrida com a MINASTAXI esta agendada para o dia ${dataFormatada} às ${horaAgendamento}hs.\n\nPassageiros na mesma rota:\n${listaNomes}\n\n🔄 Atenção: Para clientes que utilizam rota compartilhada o horário informado refere-se ao início da rota, podendo haver pequenas variações no horário de embarque conforme a sequência dos atendimentos.\n\nPara falar com a atendente, o WhatsApp é 31 99537-6584.\n\nAtenciosamente;\nCentral de Atendimento`;
    messages.push({ json: { number: foneString, text: textoMsg, delay: 1500 } });
});

return messages;

const webhook = $('Webhook').first().json.body || $('Webhook').first().json;
const trip = webhook.trip || {};
const passengers = trip.passengers || [];
const dataAgendamento = trip.scheduledDate || "data informada";
const horaIda = (passengers.length > 0 && passengers[0].serviceTime) ? passengers[0].serviceTime : (trip.arrivalTime || trip.departureTime || "Não informado");
const horaVolta = trip.returnTime || trip.horario_retorno || "Sem retorno agendado";
const listaNomes = passengers.map(p => `• ${p.name}`).join("\n");
const textoMsg = `📊 *Relatório de Agendamentos* 🚕\n\nNovos táxis foram solicitados para o dia *${dataAgendamento}*.\n\n🕐 *Horário de Ida:* ${horaIda}\n🕢 *Horário de Retorno:* ${horaVolta}\n\n*Passageiros da corrida:*\n${listaNomes}`;
const numerosGestores = ["5531985628956", "5531999999926"];
const messages = [];
numerosGestores.forEach(numero => { messages.push({ json: { number: numero.trim(), text: textoMsg } }); });
return messages;

// ==========================================
// 1. Puxa o JSON do nó anterior (Code in JavaScript - IDA)
// que já contém _geocode_cache com todas as coordenadas processadas
// ==========================================
const idaJson = $input.first().json;
const geocodeCache = idaJson._geocode_cache || {};
const destInfo = geocodeCache.destInfo || { lat: "", lng: "", neighborhood: "", city: "", state: "", postal_code: "" };
const userInfo = geocodeCache.userInfo || {};
const dadosOrganizados = geocodeCache.dadosOrganizados || [];

// ==========================================
// 2. Puxa o JSON bruto do Webhook
// ==========================================
const webhook = $('Webhook').first().json.body || $('Webhook').first().json;
const tripInfo = webhook.trip || {};

// ==========================================
// 3. TRAVA DE SEGURANÇA
// ==========================================
const timeString = tripInfo.returnTime || tripInfo.horario_retorno || "";
if (!timeString || timeString.trim() === "" || timeString === "00:00") {
    console.log("Corrida sem horário de volta. Abortando.");
    return [];
}

// ==========================================
// 4. Montagem do pickup_time de VOLTA
// Usa scheduledReturnDate se vier, senão usa scheduledDate
// ==========================================
const dataVolta = tripInfo.scheduledReturnDate || tripInfo.scheduledDate || "";
let pickupTimeUnix = Math.floor(Date.now() / 1000);
try {
    if (dataVolta) {
        let [d, m, y] = dataVolta.split('/');
        let [h, min] = timeString.split(':');
        if (!y) y = new Date().getFullYear().toString();
        else if (y.length === 2) y = "20" + y;
        const pad = (num) => String(num).padStart(2, '0');
        const dataIsoBRT = `${y}-${pad(m)}-${pad(d)}T${pad(h || 0)}:${pad(min || 0)}:00-03:00`;
        const dateObj = new Date(dataIsoBRT);
        if (!isNaN(dateObj.getTime())) pickupTimeUnix = Math.floor(dateObj.getTime() / 1000);
    }
} catch (e) { console.log("Erro na data de volta: ", e); }

// ==========================================
// 5. INVERSÃO DOS PASSAGEIROS (último embarca primeiro na volta)
// ==========================================
const passageirosIda = dadosOrganizados.filter(p => p.type === "passageiro");
const passageirosVolta = [...passageirosIda].reverse();

const finalUsers = passageirosVolta.map((u, index) => {
    const original = tripInfo.passengers?.find(p => p.name === u.name) || {};
    return {
        id: u.id,
        sequence: (index * 2) + 1,
        name: u.name,
        phone: u.phone.replace(/\D/g, ""),
        passenger_re: original.re || "",
        passenger_cost_center: u.costCenter,
        // Na VOLTA: embarca na EMPRESA (destInfo = coordenadas do destino da ida)
        pickup: {
            address: tripInfo.destinations?.[0]?.location?.address || "",
            neighborhood: destInfo.neighborhood,
            city: destInfo.city,
            state: destInfo.state,
            postal_code: destInfo.postal_code,
            lat: destInfo.lat,
            lng: destInfo.lng
        }
    };
});

const finalDestinations = passageirosVolta.map((u, index) => {
    const info = userInfo[u.id] || { lat: "", lng: "", neighborhood: "", city: "", state: "", postal_code: "" };
    return {
        passengerId: u.id,
        sequence: (index * 2) + 2,
        // Na VOLTA: desce em CASA (userInfo = coordenadas do passageiro)
        location: {
            address: u.original_address,
            neighborhood: info.neighborhood,
            city: info.city,
            state: info.state,
            postal_code: info.postal_code,
            reference: "",
            lat: info.lat,
            lng: info.lng
        }
    };
});

// ==========================================
// 6. RETORNO FINAL DA VOLTA
// ==========================================
return {
    partner: "322",
    user: tripInfo.company?.replace(/\D/g, "") || "CNPJ_VAZIO",
    password: "0104",
    request_id: `REQ-VOLTA-${Date.now()}`,
    pickup_time: pickupTimeUnix.toString(),
    distance: "0",
    stopped_time: "0",
    category: "taxi",
    passengers_no: finalUsers.length,
    send_sms: 1,
    suitcases_no: 0,
    requester_name: `${tripInfo.requester || ''}`,
    extra1: $('Webhook').first().json.body.trip.extra1,
    extra2: tripInfo.requester,
    payment_type: $('Webhook').first().json.body.trip.payment,
    users: finalUsers,
    destinations: finalDestinations,
    tipo_rota: "VOLTA"
};
